def normalizeFilepath(self, filepath: str, url: str, cacheDir: str | None = None) -> str:
    """
    Perform any necessary transformations to filepath.
    :param filepath: Filepath to normalize.
    :param url: Original URL (for http/https redirect).
    :param cacheDir: Cache root directory.
    :return: Normalized filepath.
    """
    if cacheDir is None:
        cacheDir = self.cacheDir

    if self.httpsRedirect:
        if not os.path.exists(filepath):
            # if enabled, check for missing files in their inverse http/https cache directory
            redirect = None
            if url.startswith("http://"):
                redirect = self.urlToCacheFilepath("https" + url[4:], cacheDir=cacheDir)
            elif url.startswith("https://"):
                redirect = self.urlToCacheFilepath("http" + url[5:], cacheDir=cacheDir)

            if redirect and os.path.exists(redirect):
                filepath = redirect

    if filepath.endswith("/"):
        filepath += DIRECTORY_INDEX_FILE

    if os.sep == "\\":
        filepath = filepath.replace("/", "\\")

    return filepath

def normalizeUrl(self, url: str | None, base: str | None = None) -> Any:
    cacheKey = (url, base)
    if result := self._normalizeUrlCache.get(cacheKey):
        return result

    if url:
        url = url.removeprefix("file://")
        url = url.removeprefix("file:\\")

    normedPath: str | None
    if url and not (isHttpUrl(url) or isLegacyAbs(url)):
        if base is not None and not isHttpUrl(base) and "%" in url:
            url = unquote(url)

        if base:
            if isHttpUrl(base):
                scheme, sep, path = base.partition("://")
                normedPath = scheme + sep + posixpath.normpath(os.path.dirname(path) + "/" + url)
            else:
                if "%" in base:
                    base = unquote(base)
                normedPath = os.path.normpath(os.path.join(os.path.dirname(base), url))

        else: # includes base == '' (for forcing relative path)
            normedPath = url

        normedPath = normedPath.removeprefix("file://")
        normedPath = normedPath.removeprefix("file:\\")

        # no base, not normalized, must be relative to current working directory
        if base is None and not isLegacyAbs(url):
            normedPath = os.path.abspath(normedPath)
    else:
        normedPath = url

    if normedPath:
        if isHttpUrl(normedPath):
            scheme, sep, pathpart = normedPath.partition("://")
            pathpart = pathpart.replace("\\","/")
            endingSep = "/" if pathpart[-1] == "/" else ""  # normpath drops ending directory separator
            normedPath = scheme + "://" + posixpath.normpath(pathpart) + endingSep
        else:
            normedPath = os.path.normpath(normedPath)
            if normedPath.startswith(self.cacheDir):
                normedPath = self.cacheFilepathToUrl(normedPath)

    self._normalizeUrlCache[cacheKey] = normedPath
    return normedPath

def baseForElement(self, element: ModelObject) -> str:
    base = ""
    baseElt = element
    while baseElt is not None:
        baseAttr = baseElt.get("{http://www.w3.org/XML/1998/namespace}base")
        if baseAttr:
            if self.modelXbrl.modelManager.validateDisclosureSystem:
                self.modelXbrl.error(("EFM.6.03.11", "GFM.1.1.7", "EBA.2.1", "EIOPA.2.1"),
                    _("Prohibited base attribute: %(attribute)s"),
                    edgarCode="du-0311-Xml-Base-Used",
                    modelObject=element, attribute=baseAttr, element=element.qname)
            else:
                """ HF 2019-09-29: believe this is wrong
                if baseAttr.startswith("/"):
                    base = baseAttr
                else:
                    base = baseAttr + base
                """
                base = baseAttr + base
                if base.startswith("/"):
                    break # break because it is now absolute
        baseElt = baseElt.getparent()  # type: ignore[assignment]
    if base: # neither None nor ''
        if base.startswith("http://") or isLegacyAbs(base):
            return base
        else:
            return os.path.dirname(self.uri) + "/" + base
    return self.uri

def discoverHref(self, element: ModelObject, nonDTS: bool = False, urlRewritePluginClass: str | None = None) -> tuple[ModelObject, ModelDocument | None, str | None] | None:
    href = element.get("{http://www.w3.org/1999/xlink}href")
    if href:
        url, id = UrlUtil.splitDecodeFragment(href)
        if url == "":
            doc: Any = self
        else:
            # href discovery only can happein within a DTS
            _newDoc: Any
            if self.skipDTS: # no discovery
                _newDoc = DocumentPrototype
            else:
                _newDoc = load
            if urlRewritePluginClass:
                for pluginMethod in self.modelXbrl.modelManager.cntlr.plugins.hooks(urlRewritePluginClass):
                    url = pluginMethod(self, url)
            doc = _newDoc(self.modelXbrl, url, isDiscovered=not nonDTS, base=self.baseForElement(element), referringElement=element)
            if not nonDTS and doc is not None:
                if doc not in self.referencesDocument:
                    if not doc.inDTS and doc.type > Type.UnknownTypes:    # non-XBRL document is not in DTS
                        doc.inDTS = True    # now known to be discovered
                        if doc.type == Type.SCHEMA and not self.skipDTS: # schema coming newly into DTS
                            doc.schemaDiscoverChildElements(doc.xmlRootElement)
                self.addDocumentReference(doc, "href", element)
        hrefTuple = (element, doc, id if len(id) > 0 else None)

    self.addToLog(f"sys.argv {sys.argv}", messageCode="info")

